steps.script:
var ph = PhaseManager.get_current_phase_instance()
var cap = float(ph.active_moves.get("U_WOLF_GUARD_BATTLE_LEADER_A", {}).get("move_cap_inches", 0.0))
print("[sw11e wolf-touched] move cap = ", cap)
return int(round(cap))

var mc = tree.root.get_node("Main").movement_controller
print("[sw11e wolf-touched] move_cap_label = ", mc.move_cap_label.text)
return mc.move_cap_label.text.contains("9")

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[sw11e log] ", DebugLogger.get_real_log_file_path(), " ERROR lines = ", n, " ", bad.slice(0, 3))
return n
